import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import type { EngagementReport } from '@/types/insights'
import { AD_SPOT_TIMELINE } from '@/types/timeline/__tests__/adSpotFixture'
import { buildReportModel, hookWindowSec } from '../reportModel'
import { percentDelta } from '../stepSeries'

/**
 * The reports under `e2e/stub/data/engagement/reports/` are generated by the
 * server's own maths (`api/engagement_signals`) on the ad-spot timeline. The
 * range averages computed in the browser must reproduce the server's figures,
 * otherwise the range inspector would disagree with the rest of the report.
 */
function loadReport(name: string): EngagementReport {
  const url = new URL(`../../../../e2e/stub/data/engagement/reports/${name}.json`, import.meta.url)
  return JSON.parse(readFileSync(url, 'utf8')) as EngagementReport
}

// The server rounds averages to 4 decimals and percentages to 2.
const AVERAGE_TOLERANCE = 0.00006
const PERCENT_TOLERANCE = 0.011

describe.each(['template-jumpy', 'barc', 'template-slow_burn'])('browser range averages against the server report %s', (name) => {
  const report = loadReport(name)
  const model = buildReportModel(report)
  const series = model.primary.series

  it('reproduces every per-segment average and its delta against the overall average', () => {
    expect(report.segments.length).toBe(AD_SPOT_TIMELINE.segments.length)
    for (const stat of report.segments) {
      const segment = AD_SPOT_TIMELINE.segments.find((item) => item.id === stat.segment_id)
      const mean = segment ? series.mean(segment.start_sec, segment.end_sec) : null
      expect(mean, stat.segment_id).not.toBeNull()
      expect(Math.abs((mean ?? 0) - stat.avg), stat.segment_id).toBeLessThan(AVERAGE_TOLERANCE)
      expect(Math.abs(percentDelta(mean ?? 0, series.overallMean) - stat.delta_pct), stat.segment_id).toBeLessThan(PERCENT_TOLERANCE)
    }
  })

  it('reproduces every driver average, coverage and delta from the driver ranges', () => {
    expect(report.influence.length).toBeGreaterThan(10)
    for (const driver of report.influence) {
      const total = driver.ranges.reduce(
        (sum, range) => {
          const slice = series.over(range.start_sec, range.end_sec)
          return { area: sum.area + slice.area, cover: sum.cover + slice.cover }
        },
        { area: 0, cover: 0 },
      )
      expect(Math.abs(total.cover - driver.coverage_sec), driver.key).toBeLessThan(0.0051)
      expect(Math.abs(total.area / total.cover - driver.avg_during), driver.key).toBeLessThan(AVERAGE_TOLERANCE)
      expect(Math.abs(percentDelta(total.area / total.cover, series.overallMean) - driver.delta_pct), driver.key).toBeLessThan(PERCENT_TOLERANCE)
    }
  })

  it('reproduces the hook average and the overall average', () => {
    const hook = series.mean(0, hookWindowSec(report.duration_sec))
    expect(Math.abs((hook ?? 0) - (report.kpis.hook_avg ?? Number.NaN))).toBeLessThan(AVERAGE_TOLERANCE)
    expect(Math.abs(series.overallMean - report.stats.avg)).toBeLessThan(AVERAGE_TOLERANCE)
  })

  it('finds each extremum on the smoothed curve at its reported time and value', () => {
    const smoothed = new Map(report.smoothed.map(([time, value]) => [time, value]))
    for (const extremum of report.extrema) {
      expect(smoothed.get(extremum.time_sec), extremum.id).toBe(extremum.value)
    }
  })
})
